CREATE UNIQUE INDEX students_phone_unique_idx
ON students (trim(phone))
WHERE trim(phone) <> '';

-- Match docs/database.drawio; preserve retained columns, IDs, and weekly schedules.

-- A private production backup is required before applying this migration.

CREATE TABLE _migration_course_schedule AS SELECT id AS course_id, day_one AS day_of_week, start_time_one AS start_time, end_time_one AS end_time FROM courses UNION ALL SELECT id, day_two, start_time_two, end_time_two FROM courses WHERE day_two IS NOT NULL;

CREATE UNIQUE INDEX students_phone_unique_idx
ON students (trim(phone))
WHERE trim(phone) <> '';

CREATE TABLE admin_profiles (
  email TEXT PRIMARY KEY COLLATE NOCASE,
  name TEXT NOT NULL,
  picture TEXT
);

CREATE TABLE "courses" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0)
);

CREATE TABLE subscription (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL CHECK (length(trim(name)) > 0)
);

CREATE TABLE subscription_courses (
  subscription_id INTEGER NOT NULL REFERENCES subscription(id),
  course_id INTEGER NOT NULL REFERENCES courses(id),
  entries INTEGER NOT NULL CHECK (typeof(entries) = 'integer' AND entries > 0),
  PRIMARY KEY (subscription_id, course_id)
);

CREATE TABLE attendance (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  student_course_entry_id INTEGER NOT NULL REFERENCES student_course_entries(id),
  attended_at TEXT NOT NULL,
  recorded_by TEXT NOT NULL COLLATE NOCASE REFERENCES admin_profiles(email)
);

-- Each row consumes one entry. Validate available balance and starts_on atomically.
-- paid_at is informational and must not block attendance.

INSERT INTO course_schedule (course_id, day_of_week, start_time, end_time) SELECT course_id, day_of_week, start_time, end_time FROM _migration_course_schedule;

-- Existing options remain per-course. Any-course options have one shared allowance.
ALTER TABLE subscription ADD COLUMN allowance_type TEXT NOT NULL DEFAULT 'per_course'
  CHECK (allowance_type IN ('per_course', 'any_course'));

CREATE TABLE _any_course_attendance AS
  SELECT a.id, a.student_course_entry_id, e.course_id, a.attended_at, a.recorded_by
  FROM attendance a JOIN student_course_entries e ON e.id = a.student_course_entry_id;

-- Each row consumes one entry. Validate available balance and starts_on atomically.
-- paid_at is informational and must not block attendance.
CREATE INDEX attendance_course_idx ON attendance (course_id, attended_at);

-- Explicit course assignments are independent of entry balances and attendance.
CREATE TABLE student_courses (
  student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  course_id INTEGER NOT NULL REFERENCES courses(id),
  PRIMARY KEY (student_id, course_id)
);

-- Reusable defaults only; recorded student payments retain their own values.
CREATE TABLE payment_presets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  amount_minor INTEGER NOT NULL CHECK (typeof(amount_minor) = 'integer' AND amount_minor BETWEEN 1 AND 99999999)
);

CREATE TABLE payment_preset_courses (
  preset_id INTEGER NOT NULL REFERENCES payment_presets(id) ON DELETE CASCADE,
  course_id INTEGER NOT NULL REFERENCES courses(id),
  allowance INTEGER NOT NULL CHECK (typeof(allowance) = 'integer' AND allowance BETWEEN 1 AND 10000),
  PRIMARY KEY (preset_id, course_id)
);

CREATE TRIGGER cancellation_requires_no_attendance BEFORE INSERT ON class_cancellations
WHEN EXISTS (SELECT 1 FROM attendance WHERE course_id = NEW.course_id AND attended_at = NEW.class_date || 'T' || NEW.start_time || ':00')
BEGIN SELECT RAISE(ABORT, 'Class already has attendance'); END;

CREATE TRIGGER attendance_requires_active_class BEFORE INSERT ON attendance
WHEN EXISTS (SELECT 1 FROM class_cancellations WHERE course_id = NEW.course_id AND class_date || 'T' || start_time || ':00' = NEW.attended_at)
BEGIN SELECT RAISE(ABORT, 'Class is cancelled'); END;

UPDATE classes SET end_time = (
  SELECT end_time FROM course_schedule WHERE course_id = classes.course_id AND start_time = classes.start_time
  AND day_of_week = CASE strftime('%w', classes.class_date)
  WHEN '0' THEN 'Sunday' WHEN '1' THEN 'Monday' WHEN '2' THEN 'Tuesday' WHEN '3' THEN 'Wednesday'
  WHEN '4' THEN 'Thursday' WHEN '5' THEN 'Friday' WHEN '6' THEN 'Saturday' END LIMIT 1
);

CREATE TRIGGER cancellation_requires_no_attendance BEFORE UPDATE OF cancelled ON classes
WHEN NEW.cancelled = 1 AND EXISTS (SELECT 1 FROM attendance WHERE class_id = NEW.id)
BEGIN SELECT RAISE(ABORT, 'Class already has attendance'); END;

-- A single attendance can contain one optional donation. Stop before changing
-- records if legacy donations cannot be moved without losing their identity.
CREATE TABLE practice_migration_guard (safe INTEGER NOT NULL CHECK (safe = 1));

CREATE TRIGGER practice_attendance_keeps_donation BEFORE DELETE ON practice_attendance
WHEN OLD.donation_amount_minor IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'Remove the donation before removing attendance.'); END;

CREATE TABLE administrator_payment_methods (
  email TEXT NOT NULL COLLATE NOCASE REFERENCES admin_profiles(email),
  method TEXT NOT NULL COLLATE NOCASE CHECK (length(method) BETWEEN 1 AND 50),
  PRIMARY KEY (email, method)
);

-- A course supplies the default rent for future occurrences. Each recorded
-- class keeps its own snapshot so historical rent amounts remain accurate.
ALTER TABLE courses ADD COLUMN class_cost_minor INTEGER NOT NULL DEFAULT 0 CHECK (class_cost_minor >= 0);

-- Rent is set per weekly class slot. Keep the old course-level value only as
-- legacy data, and copy it into existing schedule rows during the transition.
ALTER TABLE course_schedule ADD COLUMN rent_cost_minor INTEGER NOT NULL DEFAULT 0 CHECK (rent_cost_minor >= 0);

-- Historical class-credit records can have no monetary amount while still
-- granting valid course allowances. Preserve all payment IDs and audit data.
PRAGMA foreign_keys = OFF;

INSERT INTO student_payments_rebuilt (id, student_id, paid_on, amount_minor, notes, recorded_by, recorded_at, request_key, request_payload, given_to_school, received_method)
SELECT id, student_id, paid_on, amount_minor, notes, recorded_by, recorded_at, request_key, request_payload, given_to_school, received_method
FROM student_payments;

UPDATE sqlite_sequence
SET seq = MAX(seq, COALESCE((SELECT seq FROM _student_payment_sequence), seq))
WHERE name = 'student_payments';

-- Every administrator can always record a cash payment.
INSERT OR IGNORE INTO administrator_payment_methods (email, method)
SELECT email, 'CASH' FROM admin_profiles;

-- Preserve an explicitly recorded method; fill only historical blanks.
UPDATE student_payments SET received_method = 'CASH'
WHERE trim(received_method) = '';

CREATE TRIGGER ensure_administrator_cash_payment_method
AFTER INSERT ON admin_profiles
BEGIN
  INSERT OR IGNORE INTO administrator_payment_methods (email, method)
  VALUES (NEW.email, 'CASH');
END;

-- Preserve existing saved selections; draft rows intentionally match nobody.
ALTER TABLE payment_transfer_filters ADD COLUMN collector_emails TEXT NOT NULL DEFAULT '[]'
  CHECK (json_valid(collector_emails) AND json_type(collector_emails) = 'array');

-- A course can grant class credit before its price is decided, so its preset
-- must be able to carry a zero amount.
PRAGMA defer_foreign_keys = ON;

CREATE TABLE payment_presets_rebuilt (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 120),
  amount_minor INTEGER NOT NULL CHECK (typeof(amount_minor) = 'integer' AND amount_minor BETWEEN 0 AND 99999999),
  course_id INTEGER REFERENCES courses(id)
);

CREATE TABLE task_board_state (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  revision INTEGER NOT NULL DEFAULT 0 CHECK (typeof(revision) = 'integer' AND revision >= 0)
);

-- Include import/clear operations in revision invalidation, not just task APIs.
CREATE TRIGGER manual_tasks_insert_revision AFTER INSERT ON manual_tasks
BEGIN UPDATE task_board_state SET revision = revision + 1 WHERE id = 1; END;

-- Historical generated-task storage; retired by migration 0058.
CREATE TABLE task_rule_state (
  rule_key TEXT PRIMARY KEY CHECK (length(rule_key) BETWEEN 1 AND 80),
  activated_on TEXT NOT NULL CHECK (length(activated_on) = 10 AND date(activated_on, '+0 days') IS NOT NULL AND date(activated_on, '+0 days') = activated_on),
  evaluated_on TEXT NOT NULL CHECK (length(evaluated_on) = 10 AND date(evaluated_on, '+0 days') IS NOT NULL AND date(evaluated_on, '+0 days') = evaluated_on AND evaluated_on >= activated_on)
);

CREATE TRIGGER task_student_update_revision AFTER UPDATE OF birth_date, active, first_name, last_name ON students
WHEN NEW.birth_date IS NOT OLD.birth_date OR NEW.active IS NOT OLD.active OR NEW.first_name IS NOT OLD.first_name OR NEW.last_name IS NOT OLD.last_name
BEGIN UPDATE task_board_state SET revision = revision + 1 WHERE id = 1; END;

-- SQLite requires NULL when adding a REFERENCES column to a populated table.
-- Triggers below enforce required placement on all subsequent writes.
ALTER TABLE manual_tasks ADD COLUMN list_id INTEGER REFERENCES task_lists(id) ON DELETE RESTRICT;

CREATE TRIGGER manual_task_placement_insert BEFORE INSERT ON manual_tasks
WHEN NEW.list_id IS NOT NULL AND NEW.inbox_owner IS NOT NULL
BEGIN SELECT RAISE(ABORT, 'Choose a shared list or a personal Inbox.'); END;

CREATE TRIGGER manual_task_shared_default AFTER INSERT ON manual_tasks
WHEN NEW.list_id IS NULL AND NEW.inbox_owner IS NULL
BEGIN UPDATE manual_tasks SET list_id = 1 WHERE id = NEW.id; END;

CREATE TRIGGER manual_task_placement_update BEFORE UPDATE OF list_id, inbox_owner ON manual_tasks
WHEN (NEW.list_id IS NULL) = (NEW.inbox_owner IS NULL)
BEGIN SELECT RAISE(ABORT, 'Choose a shared list or a personal Inbox.'); END;

CREATE TRIGGER task_list_board_immutable BEFORE UPDATE OF board_id ON task_lists
WHEN NEW.board_id != OLD.board_id
BEGIN SELECT RAISE(ABORT, 'A task list cannot change boards.'); END;

-- Lists are the only task workflow; preserve every existing student relationship.
CREATE TABLE task_students (
  task_id INTEGER NOT NULL REFERENCES manual_tasks(id) ON DELETE CASCADE,
  student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE RESTRICT,
  PRIMARY KEY (task_id, student_id)
);

-- Shared list/board colors and an administrator's private Inbox appearance.
CREATE TABLE task_preferences (
  email TEXT PRIMARY KEY COLLATE NOCASE REFERENCES admin_profiles(email) ON DELETE CASCADE,
  inbox_color TEXT NOT NULL DEFAULT 'default' CHECK(inbox_color IN ('default','navy','ocean','blue','plum','lilac','sunset','rose','lagoon','slate','ember','azure','gold','green','brick','purple','pink','mint','cyan','gray'))
);

-- Per-administrator task view preferences. Inbox dimensions stay browser-local.
ALTER TABLE task_preferences ADD COLUMN selected_board_scope TEXT NOT NULL DEFAULT 'school'
  CHECK(selected_board_scope IN ('school', 'personal'));

CREATE TABLE task_courses (
  task_id INTEGER NOT NULL REFERENCES manual_tasks(id) ON DELETE CASCADE,
  course_id INTEGER NOT NULL REFERENCES courses(id) ON DELETE RESTRICT,
  PRIMARY KEY (task_id, course_id)
);

CREATE TABLE task_image_deletions (
  object_key TEXT PRIMARY KEY,
  created_at TEXT NOT NULL
);

CREATE TRIGGER task_images_delete_object AFTER DELETE ON task_images
BEGIN
  INSERT OR IGNORE INTO task_image_deletions(object_key, created_at) VALUES (OLD.object_key, CURRENT_TIMESTAMP);
END;

-- One financial record; group members each receive the full course allowances.
ALTER TABLE payment_presets ADD COLUMN student_count INTEGER NOT NULL DEFAULT 1
  CHECK (typeof(student_count) = 'integer' AND student_count BETWEEN 1 AND 10000);

CREATE TABLE payment_students (
  payment_id INTEGER NOT NULL REFERENCES student_payments(id) ON DELETE CASCADE,
  student_id INTEGER NOT NULL REFERENCES students(id),
  PRIMARY KEY (payment_id, student_id)
);

-- Free Events previously shared the Practice Parties permission. Preserve that
-- access when upgrading existing administrator records.
UPDATE administrator_permissions SET can_free_events = can_practice_parties;

CREATE TABLE task_free_events (
  task_id INTEGER NOT NULL REFERENCES manual_tasks(id) ON DELETE CASCADE,
  event_id INTEGER NOT NULL REFERENCES free_events(id) ON DELETE RESTRICT,
  PRIMARY KEY (task_id, event_id)
);

CREATE TABLE task_free_meetings (
  task_id INTEGER NOT NULL REFERENCES manual_tasks(id) ON DELETE CASCADE,
  meeting_id INTEGER NOT NULL REFERENCES free_event_meetings(id) ON DELETE RESTRICT,
  PRIMARY KEY (task_id, meeting_id)
);
